typedef unsigned long компютер_Калимабозӣ;
static компютер_Калимабозӣ 동적기억공간[8192];static unsigned 사용량;
void 자바실패(void){const char Матн[]="AOT runtime error\n";навиштан_файл_иттилоот(2,Матн,sizeof(Матн)-1);사용자호출(6,1,0,0,0,0,0);for(;;){}}
void 자바쌓기(компютер_Калимабозӣ *ҷамъ_Захирагоҳ,int *깊이,компютер_Калимабозӣ қимат){if(*깊이<0||*깊이>=128)자바실패();ҷамъ_Захирагоҳ[(*깊이)++]=қимат;}
компютер_Калимабозӣ 자바꺼내기(компютер_Калимабозӣ *ҷамъ_Захирагоҳ,int *깊이){if(*깊이<=0||*깊이>128)자바실패();return ҷамъ_Захирагоҳ[--*깊이];}
компютер_Калимабозӣ 자바배열(int 개수){if(개수<0||(unsigned)개수+1>8192-사용량)자바실패();компютер_Калимабозӣ*자료위치=동적기억공간+사용량;사용량+=개수+1;자료위치[0]=개수;return (компютер_Калимабозӣ)자료위치;}
компютер_Калимабозӣ *자바색인(компютер_Калимабозӣ объект_Маълумотнома,int 개수){компютер_Калимабозӣ*자료위치=(компютер_Калимабозӣ*)объект_Маълумотнома;if(!자료위치||개수<0||(компютер_Калимабозӣ)개수>=자료위치[0])자바실패();return 자료위치+개수+1;}
int 자바길이(компютер_Калимабозӣ объект_Маълумотнома){if(!объект_Маълумотнома)자바실패();return *(компютер_Калимабозӣ*)объект_Маълумотнома;}
int 자바나누기(int координатаи_х,int 세로좌표,int 나머지){if(!세로좌표)자바실패();if(координатаи_х==(-2147483647-1)&&세로좌표==-1)return 나머지?0:координатаи_х;return 나머지?координатаи_х%세로좌표:координатаи_х/세로좌표;}
static unsigned дарозӣ_қимат(const char*сатр_иттилоот){unsigned 개수=0;if(!сатр_иттилоот)자바실패();while(сатр_иттилоот[개수])개수++;return 개수;}
void 자바출력(компютер_Калимабозӣ 자료위치,int 수치,int 줄바꿈){
    if(수치){char 둘째값[16];unsigned 개수=0;int қимат=(int)자료위치;unsigned 부호없는값=қимат<0?0-(unsigned)қимат:қимат;do{둘째값[개수++]='0'+부호없는값%10;부호없는값/=10;}while(부호없는값);if(қимат<0)둘째값[개수++]='-';while(개수)навиштан_файл_иттилоот(1,둘째값+--개수,1);}
    else{const char*сатр_иттилоот=자료위치?(const char*)자료위치:"null";навиштан_файл_иттилоот(1,сатр_иттилоот,дарозӣ_қимат(сатр_иттилоот));}if(줄바꿈)навиштан_файл_иттилоот(1,"\n",1);
}
компютер_Калимабозӣ 자바파일쓰기(компютер_Калимабозӣ масир,компютер_Калимабозӣ қимат){const char*сатр_иттилоот=(const char*)қимат;unsigned 개수=дарозӣ_қимат(сатр_иттилоот);int файл_дастак=кушодан_файл((const char*)масир,쓰기전용|없으면만들기|내용비우기,0600);if(файл_дастак<0)자바실패();int 반환값=навиштан_файл_иттилоот(файл_дастак,сатр_иттилоот,개수);пӯшидан_файл(файл_дастак);if(반환값!=(int)개수)자바실패();return 0;}
компютер_Калимабозӣ 자바파일읽기(компютер_Калимабозӣ масир){int файл_дастак=кушодан_файл((const char*)масир,танҳо_барои_хондан_қимат,0);if(файл_дастак<0)자바실패();int 개수=файл_андоза_кардан(файл_дастак);if(개수<0||개수>16384||(unsigned)(개수+8)/8>8192-사용량)자바실패();char*자료위치=(char*)(동적기억공간+사용량);사용량+=(개수+8)/8;int 반환값=파일자료읽기(файл_дастак,자료위치,개수);пӯшидан_файл(файл_дастак);if(반환값!=개수)자바실패();자료위치[개수]=0;return (компютер_Калимабозӣ)자료위치;}
